const navigation={admin:[['Overview','LayoutDashboard'],['Approvals','ShieldCheck'],['Accounts','Users'],['Payments','HandCoins'],['Orders','ClipboardList'],['Feedback','MessageSquareText'],['Notifications','Bell'],['Platform','Settings'],['Records','FileText'],['Profile','UserRound']],vendor:[['Overview','LayoutDashboard'],['Orders','ClipboardList'],['Menu','Package'],['Inventory','SlidersHorizontal'],['Analytics','ChartNoAxesCombined'],['Balance','Wallet'],['Support','Headset'],['Profile','UserRound'],['Notifications','Bell']],rider:[['Nearby orders','MapPin'],['Deliveries','Truck'],['Wallet','Wallet'],['Submit payments','HandCoins'],['Performance','ChartNoAxesCombined'],['Support','Headset'],['Profile','UserRound'],['Notifications','Bell']],customer:[['My orders','ShoppingBag'],['Profile','UserRound'],['Feedback','MessageSquareText'],['Support','Headset'],['Notifications','Bell']]};
const Icon=({name,...props})=>{const items={LayoutDashboard,ShieldCheck,Users,HandCoins,ClipboardList,MessageSquareText,Bell,Settings,FileText,Package,SlidersHorizontal,ChartNoAxesCombined,Wallet,Headset,UserRound,MapPin,Truck,ShoppingBag};const C=items[name]||Activity;return <C size={17} {...props}/>};
const fmtDate=d=>d?new Date(d).toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}):'â€”';
function Stat({label,value,delta,icon:IconComp,accent='green'}){return <div className="card p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-[#829087]">{label}</p><p className="heading mt-2 text-2xl font-extrabold">{value}</p></div><div className={`grid h-10 w-10 place-items-center rounded-xl ${accent==='orange'?'bg-[#fff0e9] text-[#df7048]':'bg-[#eaf5ec] text-forest'}`}><IconComp size={19}/></div></div>{delta&&<div className="mt-4 flex items-center gap-1 text-[11px] font-bold text-[#4e9b68]"><ArrowUpRight size={13}/>{delta}</div>}</div>}
