const addProduct=async e=>{e.preventDefault();await msg(async()=>{await api('/products',{method:'POST',token,body:{...product,price:Number(product.price),stock:Number(product.stock),salePercent:Number(product.salePercent)}});setModal('');setProduct({name:'',category:'',description:'',price:'',stock:'',image:'',salePercent:0});notify('New dish added to menu')})};
