{tab==='Overview'&&role==='customer'&&<><SectionHeader eyebrow="Your Bite Box" title={hello} sub="All your orders and delicious next steps, in one place." button="Order something good" onClick={()=>location.href='/'}/><div className="grid gap-4 sm:grid-cols-3"><Stat label="Orders placed" value={summary.orders||0} icon={ShoppingBag}/><Stat label="Delivered" value={summary.delivered||0} icon={CheckCircle2}/><Stat label="Past orders" value="Track anytime" icon={Clock3}/></div><div className="mt-5"><Panel title="Recent orders" action={<button onClick={()=>go('My orders')} className="text-xs font-bold text-forest">All orders â†’</button>}><OrderRows orders={orders.slice(0,7)} role="customer" onAction={orderAction} feedbackAction={feedback}/></Panel></div></>}

{tab==='Approvals'&&role==='admin'&&<><SectionHeader eyebrow="People & partners" title="Account approvals" sub="Review vendor payments and rider applications before activating accounts."/><Panel title="Applications awaiting review"><div className="overflow-x-auto"><table className="w-full min-w-[740px] text-left text-xs"><thead className="bg-[#fafbf9] text-[#839087]"><tr>{['Applicant','Role','Contact','Submitted','Details','Decision'].map(x=><th key={x} className="px-5 py-3">{x}</th>)}</tr></thead><tbody>{users.filter(u=>u._bucket==='applicant'&&u.status==='pending').map(u=><tr key={u._id} className="border-t"><td className="px-5 py-4"><b>{u.name}</b><span className="block text-[10px] text-slate-400">{u.email}</span></td><td className="px-5 py-4 capitalize">{u.role}</td><td className="px-5 py-4">{u.phone}</td><td className="px-5 py-4">{fmtDate(u.createdAt)}</td><td className="px-5 py-4"><button onClick={()=>{setTarget(u);setModal('applicant')}} className="font-bold text-forest">View details</button></td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={()=>cardAction(u,'active')} className="rounded-lg bg-emerald-50 px-3 py-2 font-bold text-emerald-700">Approve</button><button onClick={()=>cardAction(u,'rejected')} className="rounded-lg bg-rose-50 px-3 py-2 font-bold text-rose-600">Decline</button></div></td></tr>)}</tbody></table>{!users.some(u=>u._bucket==='applicant'&&u.status==='pending')&&<div className="p-8"><Empty title="No applications waiting" sub="New vendor and rider requests will show up here."/></div>}</div></Panel></>}
{tab==='Accounts'&&role==='admin'&&<><SectionHeader eyebrow="Partner management" title="Accounts & access" sub="Manage vendor and rider access, reset passwords, and review account details."/><Panel title="Partner accounts"><div className="divide-y divide-[#edf0eb]">{users.filter(u=>u._bucket==='account').map(u=><div key={u._id} className="flex flex-wrap items-center gap-3 px-5 py-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#edf4ee] font-bold text-forest">{u.name?.[0]}</div><div className="min-w-[180px] flex-1"><b className="block text-sm">{u.vendor?.shopName||u.name}</b><span className="text-[10px] capitalize text-[#859188]">{u.role} Â· {u.email||u.phone}</span></div><Status value={u.status}/><button onClick={()=>{setTarget(u);setModal('account')}} className="rounded-lg border px-3 py-2 text-xs font-bold">Manage</button></div>)}</div></Panel></>}
{tab==='Payments'&&role==='admin'&&<><SectionHeader eyebrow="Finance desk" title="Payment handling" sub="Review vendor top-ups and rider remittances. Mark transfers after verification."/><div className="mb-5 grid gap-4 sm:grid-cols-3"><Stat label="Pending requests" value={records.filter(r=>['payment-submission','settlement'].includes(r.kind)&&r.status==='pending').length} icon={Clock3}/><Stat label="Vendor balances" value={money(analytics?.vendors?.reduce((s,v)=>s+(v.vendor?.currentBalance||0),0))} icon={Store}/><Stat label="Rider payouts" value={money(records.filter(r=>r.kind==='settlement'&&r.status==='pending').reduce((s,r)=>s+r.amount,0))} icon={Wallet}/></div><div className="mb-4 flex justify-end"><button onClick={()=>msg(async()=>{const d=await api('/admin/vendor-payouts/generate',{method:'POST',token});notify(`${d.created} vendor payout(s) created`)})} className="btn-primary text-xs">Generate this week's vendor payouts</button></div><Panel title="Open payment requests"><div className="divide-y">{records.filter(r=>['payment-submission','settlement'].includes(r.kind)&&r.status==='pending').map(r=><div key={r._id} className="flex flex-wrap items-center gap-3 p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#fff3e9] text-[#d77a4f]"><HandCoins size={18}/></div><div className="min-w-[190px] flex-1"><b className="block text-xs">{r.message||r.kind} · {r.user?.name||'Account'}</b><span className="text-[10px] text-[#87948c]">{r.method||'—'} · {fmtDate(r.createdAt)} {r.reference&&`· Ref ${r.reference}`}</span>{r.user?.role==='vendor'&&<span className="mt-1 block text-[10px] text-[#66756b]">{r.user.vendor?.shopName||'Vendor'} · {r.user.vendor?.account?.name||'Account'} · {r.user.vendor?.account?.method||'—'} · {r.user.vendor?.account?.number||'No account number'}</span>}{r.user?.role==='rider'&&<span className="mt-1 block text-[10px] text-[#66756b]">Rider payout account: {r.user.rider?.account?.name||'Account'} · {r.user.rider?.account?.method||'—'} · {r.user.rider?.account?.number||'No account number'} {r.user.rider?.account?.branchName&&`· ${r.user.rider.account.branchName} ${r.user.rider.account.branchCode||''}`}</span>}</div><b>{money(r.amount)}</b>{r.proofUrl&&<PrivateDocumentPreview id={r.proofUrl} token={token} label="View proof"/>}<button onClick={()=>submitPaymentAction(r,'verified')} className="rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-700">Verify</button><button onClick={()=>submitPaymentAction(r,'rejected')} className="rounded-lg bg-rose-50 px-3 py-2 text-xs font-bold text-rose-600">Reject</button></div>)}{!records.some(r=>['payment-submission','settlement'].includes(r.kind)&&r.status==='pending')&&<div className="p-8"><Empty title="No payments to verify"/></div>}</div><div className="border-t px-5 py-4"><button onClick={()=>setModal('paymentAccounts')} className="btn-light">Manage payout account details</button></div></Panel><PaymentArchive token={token} notify={notify}/></>}
{tab==='Orders'&&role==='admin'&&<><SectionHeader eyebrow="Platform operations" title="Order management" sub="Search by order ID or filter the period, review details, and cancel an order."/><div className="mb-4 flex flex-wrap gap-2"><div className="flex items-center gap-2 rounded-xl border bg-white px-3"><Search size={15} className="text-slate-400"/><input className="w-44 py-2.5 text-xs outline-none" placeholder="Search order ID" value={filter} onChange={e=>setFilter(e.target.value)}/></div><input type="date" className="rounded-xl border bg-white px-3 py-2 text-xs" onChange={e=>api(`/orders?from=${e.target.value}`,{token}).then(d=>setOrders(d.orders))}/><button className="btn-light !py-2 text-xs" onClick={load}><RefreshCw size={14} className="mr-1 inline"/>Refresh</button></div><Panel title={`${ordersForTab.length} orders`}><OrderRows orders={ordersForTab} role="admin" onAction={orderAction} feedbackAction={feedback}/></Panel></>}
