{tab==='My orders'&&role==='customer'&&<><SectionHeader eyebrow="Your order history" title="My orders" sub="Follow your meal from the kitchen to your door."/><div className="mb-4 flex items-center gap-2"><div className="flex items-center gap-2 rounded-xl border bg-white px-3"><Search size={15} className="text-slate-400"/><input className="py-2.5 text-xs outline-none" placeholder="Search by order ID or status" value={filter} onChange={e=>setFilter(e.target.value)}/></div><button onClick={load} className="btn-light !py-2 text-xs"><RefreshCw size={14}/></button></div><Panel title="Your orders"><OrderRows orders={ordersForTab} role="customer" onAction={orderAction} feedbackAction={feedback}/></Panel></>}
{tab==='Nearby orders'&&role==='rider'&&<><SectionHeader eyebrow="On the move" title="Nearby orders" sub="Choose a kitchen within 3 km. Delivery locations are up to you." button="Update my location" onClick={()=>{if(!navigator.geolocation)return notify('Location is not available in this browser','error');navigator.geolocation.getCurrentPosition(async pos=>{try{const d=await api('/auth/profile',{method:'PATCH',token,body:{rider:{...user.rider,location:{lat:pos.coords.latitude,lng:pos.coords.longitude}}}});setUser(d.user);notify('Your dispatch location was updated');load()}catch(e){notify(e.message,'error')}},e=>notify(e.message,'error'),{enableHighAccuracy:true,timeout:15000})}}/><div className="mb-4 flex items-center gap-3 rounded-2xl bg-[#eaf5ec] p-4 text-xs text-forest"><LocateFixed size={18}/><span>Use the location button to set your position for nearby dispatch orders.</span></div><div className="grid gap-4 md:grid-cols-2">{summary.nearby?.map(o=><div key={o._id} className="card p-5"><div className="flex items-start justify-between"><div><b className="heading text-lg">{o.vendor?.vendor?.shopName||o.vendor?.name}</b><p className="mt-1 text-xs text-[#829087]">Order #{o._id.slice(-7).toUpperCase()} Â· {o.items?.length} items</p></div><Status value={o.status}/></div><div className="mt-4 flex items-center gap-2 text-xs text-[#718078]"><MapPin size={15}/>{Number(o.vendorDistanceKm).toFixed(2)} km to kitchen</div><p className="mt-3 truncate text-xs text-[#829087]">{o.address}</p><div className="mt-4 flex items-center justify-between border-t pt-4"><b>{money(o.pricing?.total)}</b><button onClick={()=>changeStatus(o,'claim')} className="btn-primary !px-4 !py-2 text-xs">Accept delivery</button></div></div>)}{!summary.nearby?.length&&<div className="md:col-span-2"><Empty title="No deliveries nearby" sub="Orders appear when a vendor within 3 km has prepared one."/></div>}</div></>}
{tab==='Deliveries'&&role==='rider'&&<><SectionHeader eyebrow="Your route" title="My deliveries" sub="Update the customer as you pick up and complete each order." button={sharing?'Stop location sharing':'Share my location'} onClick={()=>setSharing(v=>!v)}/><Panel title="Assigned deliveries"><OrderRows orders={orders.filter(o=>o.rider?._id===user.id||o.rider===user.id)} role="rider" onAction={orderAction}/></Panel></>}
{tab==='Menu'&&role==='vendor'&&<><SectionHeader eyebrow="Your kitchen" title="Menu management" sub="Add dishes, adjust prices, and set the sales tag customers see." button="Add dish" onClick={()=>setModal('product')}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{summary.products?.map(p=><div key={p._id} className="card flex gap-3 p-3"><ProvidedImage src={p.image} alt={p.name} index={p.name.length} className="h-24 w-24 shrink-0 rounded-xl"/><div className="min-w-0 flex-1"><b className="block truncate">{p.name}</b><span className="text-xs text-[#89968e]">{money(p.price)} Â· {p.stock} stock</span><p className="mt-1"><Status value={p.available&&p.stock>0?'active':'suspended'}/></p><div className="mt-2 flex gap-3"><button onClick={()=>{setProduct(p);setTarget(p);setModal('editProduct')}} className="text-[11px] font-extrabold text-forest">Edit item</button><button onClick={()=>{if(window.confirm(`Delete ${p.name} from your menu?`))msg(async()=>{await api(`/products/${p._id}`,{method:'DELETE',token});notify('Dish removed')})}} className="text-[11px] font-bold text-rose-500">Delete</button></div></div></div>)}{!summary.products?.length&&<div className="sm:col-span-2 xl:col-span-3"><Empty title="Your menu is ready for its first dish" sub="Add your products, images, descriptions, stock, and sales tags."/></div>}</div></>}
{tab==='Inventory'&&role==='vendor'&&<><SectionHeader eyebrow="Freshness matters" title="Update inventory" sub="Out-of-stock dishes disappear from the customer menu until they are replenished."/><Panel title="Stock status"><div className="divide-y">{summary.products?.map(p=><InventoryRow key={p._id} product={p} updateStock={updateStock}/>)}{!summary.products?.length&&<div className="p-5"><Empty title="No products to update"/></div>}</div></Panel></>}
{tab==='Analytics'&&role==='vendor'&&<><SectionHeader eyebrow="Your numbers" title="Sales analytics" sub="View sales, commission, and earnings for the selected period."/><div className="mb-5 flex flex-wrap items-center gap-2"><select className="rounded-xl border bg-white px-3 py-2 text-xs" value={periodUnit} onChange={e=>{setPeriodUnit(e.target.value);setPeriodYear('')}}><option value="day">Daily</option><option value="month">Monthly</option><option value="year">Yearly</option></select><input type="number" className="w-24 rounded-xl border px-3 py-2 text-xs" value={periodCount} onChange={e=>setPeriodCount(Math.max(1,Math.min(periodUnit==='month'?11:99,Number(e.target.value)||1)))} min="1" max={periodUnit==='month'?11:99}/><input type="number" placeholder="Specific year" className="w-28 rounded-xl border px-3 py-2 text-xs" value={periodYear} onChange={e=>setPeriodYear(e.target.value)}/><button onClick={applyVendorPeriod} className="btn-light !py-2 text-xs">Apply period</button></div><div className="grid gap-4 sm:grid-cols-3"><Stat label="Gross food sales" value={money(orders.filter(o=>o.status==='delivered').reduce((s,o)=>s+(o.pricing?.subtotal||0),0))} icon={ReceiptText}/><Stat label="Orders delivered" value={orders.filter(o=>o.status==='delivered').length} icon={CheckCircle2}/><Stat label="Current balance" value={money(summary.balance)} icon={Wallet}/></div><div className="mt-5"><Panel title="Recent order sales"><div className="h-72 p-5"><ResponsiveContainer width="100%" height="100%"><BarChart data={orders.filter(o=>o.status==='delivered').slice(0,12).reverse().map(o=>({_id:fmtDate(o.createdAt),sales:o.pricing.subtotal,commission:o.pricing.commission}))}><CartesianGrid stroke="#edf1eb" vertical={false}/><XAxis dataKey="_id" tick={{fontSize:10}}/><Tooltip/><Bar dataKey="sales" fill="#318454" radius={[5,5,0,0]}/><Bar dataKey="commission" fill="#efa172" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Panel><div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel title="Most popular dishes"><ProductPerformance orders={orders}/></Panel><Panel title="Customer feedback"><FeedbackRows records={records.filter(r=>r.kind==='feedback')}/></Panel></div></div></>}
{(tab==='Balance'&&role==='vendor'||tab==='Wallet'&&role==='rider')&&<><SectionHeader eyebrow="Money & settlements" title={tab==='Balance'?'Vendor balance':'Rider wallet'} sub={tab==='Balance'?'Top up to keep accepting orders. Minimum balance to maintain: Rs. 200.':'Review weekly earnings and request your payout to your saved account.'}/><div className="grid gap-4 sm:grid-cols-2"><Stat label={tab==='Balance'?'Available vendor balance':'Delivered this week'} value={tab==='Balance'?money(summary.balance):money(records.filter(r=>r.kind==='settlement').reduce((s,r)=>s+r.amount,0))} icon={Wallet}/><Stat label="Open requests" value={records.filter(r=>['settlement','payment-submission'].includes(r.kind)&&r.status==='pending').length} icon={Clock3} accent="orange"/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Panel title={tab==='Balance'?'Top up your balance':'Weekly payout'}><div className="p-5"><p className="text-sm text-[#78877e]">{tab==='Balance'?`Submit a top-up request for more than Rs. ${Number(settings.minimumVendorTopUp||1500).toLocaleString()}. The admin verifies it before adding to your current balance.`:'Request a weekly payout. Earnings include Rs. 10 per km delivery pay and 10% of the capped brand commission.'}</p><button onClick={()=>setModal(tab==='Balance'?'topup':'payout')} className="btn-primary mt-5">{tab==='Balance'?'Request top-up':'Request weekly payout'}</button></div></Panel><Panel title="Account information"><div className="p-5"><p className="text-xs text-[#819087]">{user?.name}</p><p className="mt-1 text-sm font-bold">{role==='vendor'?user?.vendor?.account?.name:user?.rider?.account?.name||'Payout account not set'}</p><p className="mt-1 text-xs text-[#819087]">{role==='vendor'?user?.vendor?.account?.number:user?.rider?.account?.number}</p>{role==='rider'&&<button onClick={()=>go('Profile')} className="mt-3 text-xs font-bold text-forest">Update payout details</button>}</div></Panel></div><div className="mt-5"><Panel title="Payment history"><RecordsTable records={records.filter(r=>['settlement','payment-submission'].includes(r.kind))}/></Panel></div></>}
{tab==='Submit payments'&&role==='rider'&&<><SectionHeader eyebrow="Daily collections" title="Submit order payments" sub="Reconcile COD, JazzCash, and EasyPaisa money you collected from customers."/><div className="mb-5 grid gap-4 sm:grid-cols-3"><Stat label="Collected from delivered orders" value={money(orders.filter(o=>o.status==='delivered').reduce((s,o)=>s+o.pricing.total,0))} icon={HandCoins}/><Stat label="Awaiting verification" value={money(records.filter(r=>r.kind==='payment-submission'&&r.status==='pending').reduce((s,r)=>s+r.amount,0))} icon={Clock3}/><Stat label="Completed deliveries" value={orders.filter(o=>o.status==='delivered').length} icon={Truck}/></div><button onClick={()=>setModal('remit')} className="btn-primary mb-5">Submit collected payments</button><Panel title="Submissions"><RecordsTable records={records.filter(r=>r.kind==='payment-submission')}/></Panel></>}
{tab==='Payments'&&role==='vendor'&&null}
